public protocol LocalStoreProtocol: AnyObject, Sendable {
    
    /**
     * After `OctaPassServer.changeMasterPassword`: keeps the session's new account bundle, so
     * the next unlock takes the new password, and turns device unlock off (a new master password
     * starts it from scratch).
     */
    func updateAccount(session: Session) throws 
    
    func accountId()  -> String?
    
    func deviceUnlockStatus()  -> DeviceUnlockStatus
    
    /**
     * Turns device unlock off. Also do this on sign-out, master password change and key
     * rotation (plan 03), and delete the app's device secret.
     */
    func disableDeviceUnlock() throws 
    
    func email()  -> String
    
    /**
     * Turns on device unlock: wraps the account key with `device_secret`, 32 random bytes the
     * app keeps behind the device's lock (a Keychain item with `.biometryCurrentSet` or
     * `.devicePasscode`, or an Android Keystore key that needs `BIOMETRIC_STRONG` or
     * `DEVICE_CREDENTIAL`). Only the wrapped key is stored here; the secret never is.
     */
    func enableDeviceUnlock(session: Session, deviceSecret: Data) throws 
    
    /**
     * Items changed here that `OctaPassServer.uploadPending` still has to send.
     */
    func hasPendingChanges()  -> Bool
    
    /**
     * Re-reads the file, to see what the app or another extension wrote since `open`.
     */
    func reload() throws 
    
    func serverUrl()  -> String
    
    /**
     * Unlocks with the 32-byte device secret released by Face ID / Touch ID / fingerprint or the
     * device passcode (see `enableDeviceUnlock`). Fails with `PasswordRequired` when device
     * unlock is off or the master password is due, and `DeviceUnlockFailed` when the secret
     * doesn't open the account.
     */
    func unlockWithDevice(deviceSecret: Data) throws  -> Session
    
    /**
     * Unlocks with the master password and the Secret Key kept on this device. Runs Argon2id
     * (about a second): call it off the main thread. Restarts the 14-day device-unlock clock.
     */
    func unlockWithPassword(password: String, secretKey: String) throws  -> Session
    
    /**
     * Seals a login into the inbox, without unlocking (the Autofill service's Save). It's added to
     * the vault at the next unlock. Fails when no unlock pinned a key yet, or the inbox is full.
     */
    func addToInbox(url: String, username: String?, password: String, title: String?) throws 
    
    /**
     * Whether a login can be saved while locked: an unlock here pinned the inbox key, and the
     * inbox isn't full (50 entries).
     */
    func inboxAccepts()  -> Bool
    
    /**
     * Pins this account's own public keys for the inbox, then merges what waits in it into the
     * store. Call it at every unlock; the app uploads what it added on its next sync.
     */
    func mergeInbox(session: Session) throws  -> InboxMerge
    
    /**
     * A vault on this device only, with no server behind it.
     */
    func isLocal()  -> Bool
    
    /**
     * Unlocks a local vault with the master password and, when it's bound to this device's
     * chip, the chip's secret. Runs Argon2id: call it off the main thread. Restarts the 14-day
     * device-unlock clock. A wrong password fails with `LoginFailed`.
     */
    func unlockLocal(password: String, chipSecret: Data?) throws  -> Session
    
    /**
     * A fill key for the session's account that works until `expires_at_ms` (ms since 1970):
     * keep it in the same kind of platform item as the stay-unlocked key, and delete it when the
     * app's vault locks.
     */
    func fillKey(session: Session, expiresAtMs: UInt64) throws  -> Data
    
    /**
     * The 14-day master password check is due: the stay-unlocked key won't open the vault
     * until the master password unlocks it once.
     */
    func passwordRequired()  -> Bool
    
    /**
     * A new stay-unlocked key for the session's account: keep the bytes in the platform's
     * stay-unlocked item, never anywhere readable without the device unlocked. Each call makes a
     * new key; the old one keeps working until its item is deleted.
     */
    func stayUnlockedKey(session: Session) throws  -> Data
    
    /**
     * Unlocks with what [`fill_key`](Self::fill_key) returned, without a prompt. `None` once it
     * has expired (the app's vault has locked by now): ask as before, and delete it. Fails like
     * [`unlock_stay_unlocked`](Self::unlock_stay_unlocked) otherwise.
     */
    func unlockFillKey(key: Data) throws  -> Session?
    
    /**
     * Unlocks with what [`stay_unlocked_key`](Self::stay_unlocked_key) returned, without a
     * prompt. Fails with `PasswordRequired` while the 14-day master password check is due, and
     * `DeviceUnlockFailed` when the key doesn't open this account (delete it then).
     */
    func unlockStayUnlocked(key: Data) throws  -> Session
    
}
