public protocol OctaPassServerProtocol: AnyObject, Sendable {
    
    /**
     * A new master password, after checking the current one (`LoginFailed` when it's wrong).
     * The Secret Key and recovery code stay; every other device is signed out. `session` keeps
     * the new bundle: then call `LocalStore.updateAccount(session)`, and delete the device unlock
     * secret. Runs Argon2id twice; call it off the main thread.
     */
    func changeMasterPassword(accessToken: String, session: Session, currentPassword: String, newPassword: String, secretKey: String) throws 
    
    /**
     * Starts a reset with the recovery code: emails a code. The answer is the same for an email
     * without an account.
     */
    func startPasswordReset(email: String) throws  -> PasswordResetStart
    
    /**
     * Checks the emailed code. A wrong one fails with `Server { problemType:
     * "invalid-verification-code" }`: try again; `"recovery-expired"`: start over.
     */
    func verifyPasswordReset(resetId: String, verificationCode: String) throws  -> PasswordReset
    
    /**
     * The normalised base URL, to store with the account.
     */
    func baseUrl()  -> String
    
    /**
     * Checks the first code from the new authenticator and turns two-step sign-in on, or swaps
     * the authenticator. Returns the recovery codes when this turned it on (show them once),
     * otherwise `None`. A wrong code fails with `Server { problem_type: "invalid-second-factor" }`
     * and can be tried again; an expired setup with `Server { problem_type: "invalid-request" }`.
     */
    func confirmTotpSetup(accessToken: String, setupId: String, code: String) throws  -> [String]?
    
    /**
     * Deletes the account and everything in it, for good (plan 11). Needs a `DeleteAccount`
     * reauth token and the account email typed by the user. Then wipe all local data.
     */
    func deleteAccount(accessToken: String, reauthToken: String, confirmEmail: String) throws 
    
    /**
     * Turns two-step sign-in off: the authenticator, security keys and recovery codes are
     * removed. Needs a `TwoStep` reauth token.
     */
    func disableTwoStep(accessToken: String, reauthToken: String) throws 
    
    /**
     * Signs in with email, master password and Secret Key (needed on every new device), and
     * unlocks. Wrong credentials fail with `LoginFailed`, whichever was wrong.
     */
    func logIn(email: String, password: String, secretKey: String, device: DeviceInfo) throws  -> SignedIn
    
    /**
     * `log_in` for accounts that may have two-step sign-in: sends this device's trusted-device
     * token (from `AuthTokens`), which skips the second step while it's valid, and returns the
     * second step instead of failing when the account asks for one.
     */
    func logInTrusted(email: String, password: String, secretKey: String, device: DeviceInfo, trustedDeviceToken: String?) throws  -> LogInResult
    
    /**
     * Revokes this device's tokens. Delete the local store and device secret too.
     */
    func logOut(accessToken: String) throws 
    
    /**
     * Re-authenticates with the master password before a dangerous action and returns the
     * single-use reauth token (valid 5 minutes). Fails with `LoginFailed` before sending
     * anything if the password or Secret Key don't unlock this account. The session isn't
     * changed.
     */
    func reauth(accessToken: String, session: Session, password: String, secretKey: String, purpose: ReauthPurpose) throws  -> String
    
    func refresh(refreshToken: String) throws  -> AuthTokens
    
    /**
     * Removes a security key (they're added in a browser). Needs a `TwoStep` reauth token.
     */
    func removeSecurityKey(accessToken: String, reauthToken: String, id: String) throws 
    
    /**
