public 
enum OctaPassError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    /**
     * Wrong master password or Secret Key (locally, or at the server's OPAQUE login).
     */
    case LoginFailed
    case InvalidSecretKey
    case InvalidRecoveryCode
    /**
     * The server asked for key derivation parameters weaker than the defaults (or absurdly
     * large ones). Never retry with them.
     */
    case UnsupportedKdf
    /**
     * The device secret doesn't open this account. Turn device unlock off and on again.
     */
    case DeviceUnlockFailed
    /**
     * Device unlock is off, or the master password is due (every 14 days, plan 03).
     */
    case PasswordRequired
    /**
     * The session was locked; unlock again.
     */
    case Locked
    case InvalidTotp
    case InvalidGeneratorOptions
    case InvalidItem
    case ItemNotFound
    /**
     * The vault is read-only for this account, or there is no vault to save into.
     */
    case ReadOnlyVault
    case InvalidUrl
    /**
     * The WebAuthn request is malformed (a `TypeError` for the relying party).
     */
    case PasskeyInvalidRequest
    /**
     * The caller may not use this relying party id.
     */
    case PasskeyRpMismatch
    case PasskeyFrameNotAllowed
    case PasskeyUnsupportedAlgorithm
    /**
     * A passkey in `excludeCredentials` is already saved (`InvalidStateError`).
     */
    case PasskeyExcluded
    case PasskeyNotFound
    /**
     * A one-shot flow (sign-up, a login step) was used twice.
     */
    case FlowFinished
    /**
     * The local store file is missing, from another format version, or damaged. Sign in again
     * to rebuild it.
     */
    case InvalidStore
    case Io(reason: String
    )
    /**
     * The native `HttpClient` got no response (offline, TLS failure, timeout).
     */
    case Network(reason: String
    )
    /**
     * The server answered something that isn't the sync API.
     */
    case InvalidResponse
    /**
     * The access token expired or was revoked: refresh it, or sign in again.
     */
    case Unauthorized
    /**
     * The account was deleted on another device. Wipe this account's local data.
     */
    case AccountDeleted
    case AccountExists
    case InvalidVerificationCode
    /**
     * Any other `application/problem+json` answer. Match on `problem_type`, never on the text.
     */
    case Server(status: UInt16, problemType: String, detail: String?
    )
    /**
     * Any other core failure, by its stable code (`malformed_ciphertext`, `key_mismatch` …).
     * (Fields aren't called `message`: Kotlin exceptions already have one.)
     */
    case Core(code: String, reason: String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension OctaPassError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeOctaPassError: FfiConverterRustBuffer {
    typealias SwiftType = OctaPassError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> OctaPassError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .LoginFailed
        case 2: return .InvalidSecretKey
        case 3: return .InvalidRecoveryCode
        case 4: return .UnsupportedKdf
        case 5: return .DeviceUnlockFailed
        case 6: return .PasswordRequired
        case 7: return .Locked
        case 8: return .InvalidTotp
        case 9: return .InvalidGeneratorOptions
        case 10: return .InvalidItem
        case 11: return .ItemNotFound
        case 12: return .ReadOnlyVault
        case 13: return .InvalidUrl
        case 14: return .PasskeyInvalidRequest
        case 15: return .PasskeyRpMismatch
        case 16: return .PasskeyFrameNotAllowed
        case 17: return .PasskeyUnsupportedAlgorithm
        case 18: return .PasskeyExcluded
        case 19: return .PasskeyNotFound
        case 20: return .FlowFinished
        case 21: return .InvalidStore
        case 22: return .Io(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 23: return .Network(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 24: return .InvalidResponse
        case 25: return .Unauthorized
        case 26: return .AccountDeleted
        case 27: return .AccountExists
        case 28: return .InvalidVerificationCode
        case 29: return .Server(
            status: try FfiConverterUInt16.read(from: &buf), 
            problemType: try FfiConverterString.read(from: &buf), 
            detail: try FfiConverterOptionString.read(from: &buf)
            )
        case 30: return .Core(
            code: try FfiConverterString.read(from: &buf), 
            reason: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: OctaPassError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case .LoginFailed:
            writeInt(&buf, Int32(1))
        
        
        case .InvalidSecretKey:
            writeInt(&buf, Int32(2))
        
        
        case .InvalidRecoveryCode:
            writeInt(&buf, Int32(3))
        
        
        case .UnsupportedKdf:
            writeInt(&buf, Int32(4))
        
        
        case .DeviceUnlockFailed:
            writeInt(&buf, Int32(5))
        
        
        case .PasswordRequired:
            writeInt(&buf, Int32(6))
        
        
        case .Locked:
            writeInt(&buf, Int32(7))
        
        
        case .InvalidTotp:
            writeInt(&buf, Int32(8))
        
        
        case .InvalidGeneratorOptions:
            writeInt(&buf, Int32(9))
        
        
        case .InvalidItem:
            writeInt(&buf, Int32(10))
        
        
        case .ItemNotFound:
            writeInt(&buf, Int32(11))
        
        
        case .ReadOnlyVault:
            writeInt(&buf, Int32(12))
        
        
        case .InvalidUrl:
            writeInt(&buf, Int32(13))
        
        
        case .PasskeyInvalidRequest:
            writeInt(&buf, Int32(14))
        
        
        case .PasskeyRpMismatch:
            writeInt(&buf, Int32(15))
        
        
        case .PasskeyFrameNotAllowed:
            writeInt(&buf, Int32(16))
        
        
        case .PasskeyUnsupportedAlgorithm:
            writeInt(&buf, Int32(17))
        
        
        case .PasskeyExcluded:
            writeInt(&buf, Int32(18))
        
        
        case .PasskeyNotFound:
            writeInt(&buf, Int32(19))
        
        
        case .FlowFinished:
            writeInt(&buf, Int32(20))
        
        
        case .InvalidStore:
            writeInt(&buf, Int32(21))
        
        
        case let .Io(reason):
            writeInt(&buf, Int32(22))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .Network(reason):
            writeInt(&buf, Int32(23))
            FfiConverterString.write(reason, into: &buf)
            
        
        case .InvalidResponse:
            writeInt(&buf, Int32(24))
        
        
        case .Unauthorized:
            writeInt(&buf, Int32(25))
        
        
        case .AccountDeleted:
            writeInt(&buf, Int32(26))
        
        
        case .AccountExists:
            writeInt(&buf, Int32(27))
        
        
        case .InvalidVerificationCode:
            writeInt(&buf, Int32(28))
        
        
        case let .Server(status,problemType,detail):
            writeInt(&buf, Int32(29))
            FfiConverterUInt16.write(status, into: &buf)
            FfiConverterString.write(problemType, into: &buf)
            FfiConverterOptionString.write(detail, into: &buf)
            
        
        case let .Core(code,reason):
            writeInt(&buf, Int32(30))
            FfiConverterString.write(code, into: &buf)
            FfiConverterString.write(reason, into: &buf)
            
        }
    }
}


